import React, { useEffect, useRef, useState, useCallback } from 'react';

// Inline icons for the modal to keep it self-contained
const CloseIcon = ({ className }: { className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
    <line x1="18" y1="6" x2="6" y2="18"></line>
    <line x1="6" y1="6" x2="18" y2="18"></line>
  </svg>
);

const RotateCcwIcon = ({ className }: { className?: string }) => (
  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
    <path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 8" />
    <path d="M3 3v5h5" />
  </svg>
);

const CheckIcon = ({ className }: { className?: string }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
        <polyline points="20 6 9 17 4 12"></polyline>
    </svg>
);

interface CameraModalProps {
    onCapture: (files: File[]) => void;
    onClose: () => void;
}

export const CameraModal: React.FC<CameraModalProps> = ({ onCapture, onClose }) => {
    const videoRef = useRef<HTMLVideoElement>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const [stream, setStream] = useState<MediaStream | null>(null);
    const [error, setError] = useState<string | null>(null);
    const [facingMode, setFacingMode] = useState<'user' | 'environment'>('environment');
    const [capturedImages, setCapturedImages] = useState<File[]>([]);
    const [isFlashing, setIsFlashing] = useState(false);

    // Initialize Camera
    useEffect(() => {
        let currentStream: MediaStream | null = null;

        const startCamera = async () => {
            try {
                // Stop any existing stream
                if (stream) {
                    stream.getTracks().forEach(track => track.stop());
                }

                const newStream = await navigator.mediaDevices.getUserMedia({
                    video: { 
                        facingMode: facingMode,
                        width: { ideal: 1920 },
                        height: { ideal: 1080 }
                    },
                    audio: false
                });

                currentStream = newStream;
                setStream(newStream);

                if (videoRef.current) {
                    videoRef.current.srcObject = newStream;
                }
                setError(null);
            } catch (err) {
                console.error("Error accessing camera:", err);
                setError("Не удалось получить доступ к камере. Проверьте разрешения вашего браузера или устройства.");
            }
        };

        startCamera();

        return () => {
            if (currentStream) {
                currentStream.getTracks().forEach(track => track.stop());
            }
        };
    }, [facingMode]);

    const handleCapture = useCallback(() => {
        if (!videoRef.current || !canvasRef.current) return;

        const video = videoRef.current;
        const canvas = canvasRef.current;
        const context = canvas.getContext('2d');
        if (!context) return;

        // Visual flash effect
        setIsFlashing(true);
        setTimeout(() => setIsFlashing(false), 150);

        // Set canvas dimensions to match video
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;

        // Draw video frame to canvas
        context.drawImage(video, 0, 0, canvas.width, canvas.height);

        // Convert to blob/file
        canvas.toBlob((blob) => {
            if (blob) {
                const fileName = `camera_photo_${Date.now()}.jpg`;
                const file = new File([blob], fileName, { type: 'image/jpeg' });
                setCapturedImages(prev => [...prev, file]);
            }
        }, 'image/jpeg', 0.9);

    }, []);

    const handleDone = () => {
        if (capturedImages.length > 0) {
            onCapture(capturedImages);
        }
        onClose();
    };

    const toggleCamera = () => {
        setFacingMode(prev => prev === 'user' ? 'environment' : 'user');
    };

    return (
        <div className="fixed inset-0 z-50 bg-black flex flex-col animate-fade-in">
            {/* Main Camera View */}
            <div className="relative flex-1 overflow-hidden bg-black rounded-b-xl">
                {error ? (
                    <div className="absolute inset-0 flex items-center justify-center text-white p-6 text-center">
                        <div>
                            <p className="mb-4 text-red-400">{error}</p>
                            <button onClick={onClose} className="px-4 py-2 bg-slate-800 rounded-lg text-sm">Закрыть</button>
                        </div>
                    </div>
                ) : (
                    <video 
                        ref={videoRef} 
                        autoPlay 
                        playsInline 
                        muted 
                        className="absolute inset-0 w-full h-full object-cover" 
                    />
                )}

                {/* Flash overlay */}
                <div className={`absolute inset-0 bg-white pointer-events-none transition-opacity duration-150 ${isFlashing ? 'opacity-50' : 'opacity-0'}`} />

                {/* Top Controls */}
                <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-start bg-gradient-to-b from-black/50 to-transparent">
                    <button onClick={onClose} className="p-2 text-white hover:bg-white/20 rounded-full transition-colors" aria-label="Закрыть камеру">
                        <CloseIcon className="w-8 h-8" />
                    </button>
                    {capturedImages.length > 0 && (
                        <div className="bg-black/50 backdrop-blur-sm px-3 py-1.5 rounded-full text-white text-xs font-medium border border-white/10">
                            {capturedImages.length} фото
                        </div>
                    )}
                </div>
            </div>

            {/* Bottom Controls */}
            <div className="bg-black text-white p-6 pb-8 flex items-center justify-between gap-6">
                 {/* Switch Camera */}
                <div className="w-16 flex justify-center">
                    {!error && (
                        <button onClick={toggleCamera} className="p-3 bg-slate-800/80 rounded-full hover:bg-slate-700 transition-colors" aria-label="Переключить камеру">
                             <RotateCcwIcon className="w-6 h-6 text-white" />
                        </button>
                    )}
                </div>

                {/* Shutter Button */}
                <div className="flex-1 flex justify-center">
                    {!error && (
                        <button 
                            onClick={handleCapture}
                            className="w-20 h-20 rounded-full border-4 border-white flex items-center justify-center relative active:scale-95 transition-transform group"
                            aria-label="Сделать снимок"
                        >
                             <div className="w-16 h-16 bg-white rounded-full group-hover:bg-slate-200 transition-colors"></div>
                        </button>
                    )}
                </div>

                {/* Done Button */}
                <div className="w-16 flex justify-center">
                    {capturedImages.length > 0 ? (
                        <button onClick={handleDone} className="p-3 bg-indigo-600 rounded-full hover:bg-indigo-500 transition-colors shadow-lg shadow-indigo-900/50" aria-label="Готово">
                            <CheckIcon className="w-6 h-6" />
                        </button>
                    ) : (
                        <div className="w-12" /> /* Spacer */
                    )}
                </div>
            </div>

            {/* Hidden Canvas for Capture */}
            <canvas ref={canvasRef} className="hidden" />
        </div>
    );
};

import React, { useState, useRef, useCallback } from 'react';
import { UploadIcon } from './icons/UploadIcon';
import { CameraIcon } from './icons/CameraIcon';
import { CameraModal } from './CameraModal';

interface ImageUploaderProps {
  onAnalyze: (files: File[], condition: string) => void;
  disabled: boolean;
}

interface Thumbnail {
  id: string;
  file: File;
  previewUrl: string | null; // null while generating
}

const MAX_FILES = 5;
const THUMBNAIL_MAX_DIMENSION = 300; // max width/height for thumbnails in pixels

// --- Helper Components (inlined to avoid new files) ---

const XIcon: React.FC<{ className?: string }> = ({ className }) => (
    <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" className={className}>
      <line x1="18" y1="6" x2="6" y2="18"></line>
      <line x1="6" y1="6" x2="18" y2="18"></line>
    </svg>
);

const Spinner: React.FC = () => (
    <div className="absolute inset-0 flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-slate-200 dark:border-slate-700 border-t-indigo-500 rounded-full animate-spin"></div>
    </div>
);


// --- Thumbnail Generation Logic ---

/**
 * Creates a resized, compressed JPEG thumbnail from an image file.
 * @param file The original image file.
 * @returns A promise that resolves with a base64 Data URL of the thumbnail.
 */
const createThumbnail = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (event) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let { width, height } = img;

        if (width > height) {
          if (width > THUMBNAIL_MAX_DIMENSION) {
            height *= THUMBNAIL_MAX_DIMENSION / width;
            width = THUMBNAIL_MAX_DIMENSION;
          }
        } else {
          if (height > THUMBNAIL_MAX_DIMENSION) {
            width *= THUMBNAIL_MAX_DIMENSION / height;
            height = THUMBNAIL_MAX_DIMENSION;
          }
        }

        canvas.width = width;
        canvas.height = height;

        const ctx = canvas.getContext('2d');
        if (!ctx) {
          return reject(new Error('Could not get canvas context'));
        }
        ctx.drawImage(img, 0, 0, width, height);
        // Use JPEG for better compression of photos, with a quality setting.
        resolve(canvas.toDataURL('image/jpeg', 0.8)); 
      };
      img.onerror = reject;
      img.src = event.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};


export const ImageUploader: React.FC<ImageUploaderProps> = ({ onAnalyze, disabled }) => {
  const [thumbnails, setThumbnails] = useState<Thumbnail[]>([]);
  const [condition, setCondition] = useState<string>('Хорошее');
  const [showCamera, setShowCamera] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFiles = useCallback(async (rawFiles: FileList | File[] | null) => {
    if (!rawFiles) return;

    // Convert to array regardless of input type
    const newFilesArray = Array.isArray(rawFiles) ? rawFiles : Array.from(rawFiles);

    const acceptedFiles = newFilesArray.filter(file => file.type.startsWith('image/'));

    const uniqueNewFiles = acceptedFiles.filter(newFile => 
        !thumbnails.some(thumb => 
            thumb.file.name === newFile.name &&
            thumb.file.size === newFile.size &&
            thumb.file.lastModified === newFile.lastModified
        )
    );

    if (thumbnails.length + uniqueNewFiles.length > MAX_FILES) {
      alert(`Можно загрузить не более ${MAX_FILES} фотографий.`);
      const remainingSlots = MAX_FILES - thumbnails.length;
      uniqueNewFiles.splice(remainingSlots);
    }

    if (uniqueNewFiles.length === 0) return;

    // Create placeholder thumbnails immediately for instant UI feedback
    const placeholderThumbnails: Thumbnail[] = uniqueNewFiles.map(file => ({
        id: `${file.name}-${file.lastModified}`,
        file,
        previewUrl: null, // Indicates it's loading
    }));

    setThumbnails(prev => [...prev, ...placeholderThumbnails]);

    // Process each new file to generate a real thumbnail
    placeholderThumbnails.forEach(async (placeholder) => {
        try {
            const previewUrl = await createThumbnail(placeholder.file);
            setThumbnails(prev => prev.map(t => t.id === placeholder.id ? { ...t, previewUrl } : t));
        } catch (error) {
            console.error("Error creating thumbnail:", error);
            // Optionally remove the failed thumbnail or show an error icon
            setThumbnails(prev => prev.filter(t => t.id !== placeholder.id));
        }
    });

  }, [thumbnails]);

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    handleFiles(event.target.files);
    if(event.target) {
        event.target.value = "";
    }
  };

  const handleDrop = (e: React.DragEvent<HTMLDivElement>) => {
    e.preventDefault();
    if (e.dataTransfer.files && !disabled) {
      handleFiles(e.dataTransfer.files);
    }
  };

  const openFileDialog = () => fileInputRef.current?.click();
  const openCamera = () => setShowCamera(true);

  const handleRemoveImage = (idToRemove: string) => {
    setThumbnails(thumbs => thumbs.filter(thumb => thumb.id !== idToRemove));
  };

  const handleSubmit = () => {
    const files = thumbnails.map(t => t.file);
    if (files.length > 0) {
      onAnalyze(files, condition);
    }
  };

  return (
    <div className="w-full max-w-lg mx-auto bg-white dark:bg-slate-900 rounded-xl shadow-lg p-6 space-y-6">

      <input
        ref={fileInputRef}
        type="file"
        accept="image/*"
        multiple
        className="hidden"
        onChange={handleFileChange}
        disabled={disabled}
      />

      {showCamera && (
        <CameraModal 
            onCapture={(files) => {
                handleFiles(files);
                setShowCamera(false);
            }} 
            onClose={() => setShowCamera(false)} 
        />
      )}

      <div className="space-y-4">
        {thumbnails.length === 0 ? (
           <div 
                className={`border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-lg p-8 transition-colors ${disabled ? 'opacity-50' : 'hover:border-indigo-400 dark:hover:border-indigo-500'}`}
                onDragOver={(e) => !disabled && e.preventDefault()}
                onDrop={handleDrop}
            >
                <div className="flex flex-col items-center gap-6 text-slate-500 dark:text-slate-400">
                    <div className="text-center space-y-1">
                        <UploadIcon className="w-12 h-12 mx-auto mb-2 text-slate-400" />
                        <p className="font-semibold">Перетащите фото сюда</p>
                        <p className="text-xs">или выберите способ загрузки</p>
                    </div>

                    <div className="flex gap-3 w-full justify-center">
                        <button 
                            onClick={openFileDialog}
                            disabled={disabled}
                            className="flex-1 py-2 px-4 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
                        >
                            <UploadIcon className="w-4 h-4" />
                            Файлы
                        </button>
                        <button 
                            onClick={openCamera}
                            disabled={disabled}
                            className="flex-1 py-2 px-4 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 dark:hover:bg-slate-700 rounded-lg text-sm font-medium transition-colors flex items-center justify-center gap-2"
                        >
                            <CameraIcon className="w-4 h-4" />
                            Камера
                        </button>
                    </div>
                    <p className="text-[10px] text-slate-400">До {MAX_FILES} фото</p>
                </div>
            </div>
        ) : (
          <div className="space-y-4">
            <div className="grid grid-cols-3 gap-4">
              {thumbnails.map((thumb) => (
                <div key={thumb.id} className="relative group aspect-square bg-slate-100 dark:bg-slate-800 rounded-lg shadow-md overflow-hidden">
                  {thumb.previewUrl ? (
                    <img src={thumb.previewUrl} alt={`Предпросмотр ${thumb.file.name}`} className="w-full h-full object-cover" />
                  ) : (
                    <Spinner />
                  )}
                  <button
                    onClick={() => handleRemoveImage(thumb.id)}
                    disabled={disabled}
                    aria-label={`Удалить изображение ${thumb.file.name}`}
                    className="absolute top-1 right-1 p-1 bg-black/60 backdrop-blur-sm rounded-full text-white hover:bg-black/80 transition-all opacity-0 group-hover:opacity-100 focus:opacity-100 disabled:hidden"
                  >
                    <XIcon className="w-4 h-4" />
                  </button>
                </div>
              ))}

              {/* Add buttons when list is not full */}
              {thumbnails.length < MAX_FILES && !disabled && (
                <>
                    <button
                    onClick={openFileDialog}
                    aria-label="Загрузить файл"
                    className="flex flex-col items-center justify-center aspect-square border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-lg text-slate-500 dark:text-slate-400 hover:border-indigo-500 dark:hover:border-indigo-500 hover:text-indigo-500 dark:hover:text-indigo-400 transition-colors"
                    >
                        <UploadIcon className="w-6 h-6 mb-1" />
                        <span className="text-[10px]">Файл</span>
                    </button>
                    {/* Only show camera button if we have space for it (or if it's the only way to add if we had 4 files, we would have 1 slot left, showing both buttons might overflow grid logic if strict, but flex wrap/grid handles it) */}
                    {thumbnails.length < MAX_FILES - 1 ? (
                         <button
                         onClick={openCamera}
                         aria-label="Сделать фото"
                         className="flex flex-col items-center justify-center aspect-square border-2 border-dashed border-slate-300 dark:border-slate-600 rounded-lg text-slate-500 dark:text-slate-400 hover:border-indigo-500 dark:hover:border-indigo-500 hover:text-indigo-500 dark:hover:text-indigo-400 transition-colors"
                         >
                             <CameraIcon className="w-6 h-6 mb-1" />
                             <span className="text-[10px]">Камера</span>
                         </button>
                    ) : null}
                </>
              )}
            </div>
          </div>
        )}
      </div>

      <div className="space-y-2">
        <label htmlFor="condition-select" className="block text-sm font-medium text-slate-700 dark:text-slate-300">
          Состояние книги
        </label>
        <select
          id="condition-select"
          value={condition}
          onChange={(e) => setCondition(e.target.value)}
          disabled={disabled}
          className="w-full px-3 py-2 bg-white dark:bg-slate-800 border border-slate-300 dark:border-slate-600 rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 disabled:opacity-50"
        >
          <option value="Новая">Новая</option>
          <option value="Отличное">Отличное</option>
          <option value="Хорошее">Хорошее</option>
          <option value="Удовлетворительное">Удовлетворительное</option>
        </select>
      </div>

       <p className="text-xs text-center text-slate-500 dark:text-slate-400">
        Сфотографируйте страницу с выходными данными. Можно также добавить фото обложки и дефектов.
       </p>

       <button
        onClick={handleSubmit}
        disabled={thumbnails.length === 0 || disabled}
        className="w-full px-6 py-3 bg-indigo-600 text-white font-semibold rounded-lg shadow-md hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 transition-all disabled:bg-indigo-400 dark:disabled:bg-indigo-800 disabled:cursor-not-allowed"
       >
        Оценить книгу
       </button>
    </div>
  );
};

