const ai = new GoogleGenAI({ apiKey: process.env.API_KEY! });

const MAX_UPLOAD_DIMENSION = 1500; // Optimized for speed/quality balance (books don't need 4k)

/**
 * Resizes an image if it's too large, maintaining aspect ratio.
 * Returns a promise that resolves to a new File object.
 */
const resizeImageForUpload = (file: File): Promise<File> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (event) => {
            const img = new Image();
            img.onload = () => {
                let { width, height } = img;

                if (width <= MAX_UPLOAD_DIMENSION && height <= MAX_UPLOAD_DIMENSION) {
                    return resolve(file);
                }

                if (width > height) {
                    height *= MAX_UPLOAD_DIMENSION / width;
                    width = MAX_UPLOAD_DIMENSION;
                } else {
                    width *= MAX_UPLOAD_DIMENSION / height;
                    height = MAX_UPLOAD_DIMENSION;
                }

                const canvas = document.createElement('canvas');
                canvas.width = width;
                canvas.height = height;

                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    return reject(new Error('Could not get canvas context'));
                }
                ctx.drawImage(img, 0, 0, width, height);

                canvas.toBlob((blob) => {
                    if (!blob) {
                        return reject(new Error('Canvas to Blob conversion failed'));
                    }
                    const newFile = new File([blob], file.name, {
                        type: 'image/jpeg',
                        lastModified: Date.now()
                    });
                    resolve(newFile);
                }, 'image/jpeg', 0.85); 
            };
            img.onerror = reject;
            img.src = event.target?.result as string;
        };
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
};


async function fileToGenerativePart(file: File) {
  const base64EncodedData = await new Promise<string>((resolve) => {
    const reader = new FileReader();
    reader.onloadend = () => resolve((reader.result as string).split(',')[1]);
    reader.readAsDataURL(file);
  });
  return {
    inlineData: {
      mimeType: file.type,
      data: base64EncodedData,
    },
  };
}

