export const analyzeBookImage = async (
  files: File[],
  condition: string,
  modelName: string,
  promptTemplate: string,
): Promise<BookAnalysisResult> => {

  const userPrompt = promptTemplate.replace('{{condition}}', condition);

  // Resize images before converting them to base64
  const optimizedFiles = await Promise.all(files.map(resizeImageForUpload));
  const imageParts = await Promise.all(optimizedFiles.map(fileToGenerativePart));

  try {
    // Note: Using ai.models.generateContent with config for systemInstruction
    const response = await ai.models.generateContent({
        model: modelName,
        contents: [
            ...imageParts,
            { text: userPrompt }
        ],
        config: {
            systemInstruction: SYSTEM_INSTRUCTION,
            responseMimeType: "application/json",
            responseSchema: responseSchema,
            temperature: 0.4,
        }
    });

    const jsonText = response.text?.trim();

    if (!jsonText) {
        throw new Error("Пустой ответ от модели.");
    }

    const cleanedJsonText = jsonText.replace(/^```json\s*|^\s*```|```\s*$/g, '');

    const result = JSON.parse(cleanedJsonText);

    if (!result.bookDetails || !result.priceAnalysis || !result.adContent) {
        throw new Error("Неполный ответ от AI.");
    }

    return result as BookAnalysisResult;

  } catch (error: any) {
    console.error('Ошибка при вызове Gemini API:', error);
    let errorMessage = "Произошла ошибка при анализе изображения.";
    if (error.message) {
        if (error.message.includes('429')) errorMessage = "Слишком много запросов. Подождите немного.";
        else errorMessage += ` Детали: ${error.message}`;
    }
    throw new Error(errorMessage);
  }
};

import React, { useState, useCallback, useEffect } from 'react';
import { Header } from './components/Header';
import { ImageUploader } from './components/ImageUploader';
import { LoadingIndicator } from './components/LoadingIndicator';
import { ResultCard } from './components/ResultCard';
import { analyzeBookImage, DEFAULT_PROMPT_TEMPLATE } from './services/geminiService';
import { AppStatus, BookAnalysisResult, AppSettings, HistoryEntry } from './types';
import useLocalStorage from './hooks/useLocalStorage';
import { SettingsScreen } from './components/SettingsScreen';
import { HistoryScreen } from './components/HistoryScreen';
import { Footer } from './components/Footer';

const defaultSettings: AppSettings = {
  theme: 'dark',
  model: 'gemini-3-flash-preview',
  prompt: DEFAULT_PROMPT_TEMPLATE,
};

type ViewState = 'main' | 'history' | 'settings';

const App: React.FC = () => {
  const [settings, setSettings] = useLocalStorage<AppSettings>('bookValuerSettings', defaultSettings);
  const [history, setHistory] = useLocalStorage<HistoryEntry[]>('bookValuerHistory', []);
  const [view, setViewState] = useState<ViewState>('main');
  const [status, setStatus] = useState<AppStatus>(AppStatus.Idle);
  const [currentResult, setCurrentResult] = useState<BookAnalysisResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  // Handle browser back button (History API)
  useEffect(() => {
    const handlePopState = (event: PopStateEvent) => {
      if (event.state && event.state.view) {
        setViewState(event.state.view);
      } else {
        setViewState('main');
      }
    };

    window.addEventListener('popstate', handlePopState);
    return () => window.removeEventListener('popstate', handlePopState);
  }, []);

  const navigateTo = (newView: ViewState) => {
    if (newView === view) return;

    if (newView === 'main' && view !== 'main') {
         window.history.pushState({ view: 'main' }, '', '/');
    } else {
         window.history.pushState({ view: newView }, '', `#${newView}`);
    }
    setViewState(newView);
  };

  const handleBack = () => {
      if (window.history.state && window.history.state.view !== 'main') {
          window.history.back();
      } else {
          window.history.replaceState({ view: 'main' }, '', '/');
          setViewState('main');
      }
  };


  useEffect(() => {
    const root = window.document.documentElement;
    const isDark =
      settings.theme === 'dark' ||
      (settings.theme === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
    root.classList.toggle('dark', isDark);
  }, [settings.theme]);

  const handleImageAnalysis = useCallback(async (files: File[], condition: string) => {
    setStatus(AppStatus.Analyzing);
    setCurrentResult(null);
    setError(null);

    const imagePromises = files.map(file => new Promise<string>((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = error => reject(error);
        reader.readAsDataURL(file);
    }));

    try {
      const base64Images = await Promise.all(imagePromises);
      const result = await analyzeBookImage(files, condition, settings.model, settings.prompt);

      const newHistoryEntry: HistoryEntry = {
        id: new Date().toISOString(),
        result,
        images: base64Images,
        timestamp: Date.now(),
      };
      setHistory(prevHistory => [newHistoryEntry, ...prevHistory].slice(0, 10));

      setCurrentResult(result);
      setStatus(AppStatus.Success);
    } catch (err: any) {
      setError(err.message || 'Произошла неизвестная ошибка.');
      setStatus(AppStatus.Error);
    }
  }, [settings, setHistory]);

  const handleReset = useCallback(() => {
    setStatus(AppStatus.Idle);
    setCurrentResult(null);
    setError(null);
  }, []);

  const viewHistoryItem = (item: HistoryEntry) => {
    setCurrentResult(item.result);
    setStatus(AppStatus.Success);
    handleBack(); // Close history screen
  };

  const renderMainView = () => {
    switch (status) {
      case AppStatus.Analyzing:
        return <LoadingIndicator />;
      case AppStatus.Success:
        return currentResult ? <ResultCard result={currentResult} onReset={handleReset} /> : null;
      case AppStatus.Error:
        return (
          <div className="w-full max-w-lg mx-auto text-center p-6 bg-red-50 dark:bg-red-900/50 border border-red-200 dark:border-red-800 rounded-lg">
            <h3 className="text-lg font-semibold text-red-800 dark:text-red-200">Ошибка</h3>
            <p className="text-red-700 dark:text-red-300 mt-2 mb-4">{error}</p>
            <button
              onClick={handleReset}
              className="px-4 py-2 bg-red-600 text-white font-semibold rounded-lg shadow-md hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 transition-all"
            >
              Попробовать снова
            </button>
          </div>
        );
      case AppStatus.Idle:
      default:
        return <ImageUploader onAnalyze={handleImageAnalysis} disabled={false} />;
    }
  };

  return (
    <div className="min-h-screen flex flex-col font-sans bg-slate-50 text-slate-800 dark:bg-slate-950 dark:text-slate-200">
      <Header onSettingsClick={() => navigateTo('settings')} />
      <main className="flex-grow container mx-auto px-4 py-8 sm:py-12 flex items-center justify-center">
        {renderMainView()}
      </main>
      <Footer onHistoryClick={() => navigateTo('history')} onSettingsClick={() => navigateTo('settings')} />

      {view === 'settings' && (
        <SettingsScreen 
          settings={settings} 
          onSave={setSettings} 
          onBack={handleBack} 
        />
      )}
      {view === 'history' && (
        <HistoryScreen 
          history={history} 
          onViewItem={viewHistoryItem} 
          onBack={handleBack} 
        />
      )}
    </div>
  );
};

export default App;

